/* Minimal Warm — sand and clay neutrals, soft radii, quiet contrast */
.theme-minimal-warm {
  --bg: oklch(0.975 0.009 78.3);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.942 0.014 78.3);
  --fg: oklch(0.272 0.013 72.3);
  --fg-muted: oklch(0.52 0.025 55);
  --accent: oklch(0.6 0.11 45);
  --accent-fg: oklch(0.99 0.005 75);
  --accent-2: oklch(0.62 0.07 150);
  --line: oklch(0.907 0.018 78.2);
  --success: oklch(0.62 0.11 150);
  --warning: oklch(0.75 0.12 80);
  --danger: oklch(0.58 0.16 28);

  --radius: 0.875rem;
  --radius-sm: 0.5rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px 0 oklch(0.3 0.03 55 / 8%);
  --shadow-2: 0 10px 26px -14px oklch(0.3 0.03 55 / 30%);
  --shadow-3: 0 22px 50px -24px oklch(0.3 0.03 55 / 34%);
  --glow: 0 0 0 3px oklch(0.6 0.11 45 / 18%);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Lora", Georgia, serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.14em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-minimal-warm h1,
.theme-minimal-warm h2,
.theme-minimal-warm h3 {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-minimal-warm h1 { font-weight: 500; }
.theme-minimal-warm a, .theme-minimal-warm .text-accent { text-underline-offset: 3px; }
.theme-minimal-warm button { font-weight: 500; }

/* depth */
.theme-minimal-warm thead th { text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.7em; font-weight: 500; color: var(--fg-muted); border-bottom: 1px solid var(--line); text-align: left; }
.theme-minimal-warm td { border-bottom: 1px solid var(--line); }
.theme-minimal-warm tbody tr { transition: background 180ms ease; }
.theme-minimal-warm tbody tr:hover { background: var(--surface-2); }
.theme-minimal-warm input, .theme-minimal-warm select, .theme-minimal-warm textarea { border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface); transition: border-color 180ms ease, box-shadow 180ms ease; }
.theme-minimal-warm input:focus, .theme-minimal-warm select:focus, .theme-minimal-warm textarea:focus { outline: none; border-color: var(--accent); box-shadow: var(--glow); }
.theme-minimal-warm a { color: var(--accent); text-decoration-color: oklch(0.6 0.11 45 / 40%); text-decoration-thickness: 1px; transition: text-decoration-color 180ms ease; }
.theme-minimal-warm a:hover { text-decoration-color: var(--accent); }
.theme-minimal-warm kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.12em 0.5em; background: var(--surface-2); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: var(--radius-sm); }
.theme-minimal-warm ::selection { background: oklch(0.88 0.05 60); color: var(--fg); }
.theme-minimal-warm ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-minimal-warm ::-webkit-scrollbar-track { background: transparent; }
.theme-minimal-warm ::-webkit-scrollbar-thumb { background: oklch(0.82 0.03 60); border-radius: 9999px; border: 2px solid var(--bg); }
.theme-minimal-warm ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-minimal-warm .label-caps { color: oklch(0.55 0.08 45); }
.theme-minimal-warm .themed-border { border-left: 3px solid var(--accent); border-radius: 2px; }
/* physical: quiet press — the clay gives slightly under the finger */
.theme-minimal-warm button:active { transform: translateY(1px); box-shadow: var(--shadow-1); }

/* alt mode: dusk clay — warm ember darks, terracotta glows instead of shouts */
.theme-minimal-warm.alt-mode {
  --bg: oklch(0.17 0.012 60);
  --surface: oklch(0.21 0.014 62);
  --surface-2: oklch(0.25 0.016 62);
  --fg: oklch(0.94 0.012 78);
  --fg-muted: oklch(0.7 0.02 70);
  --accent: oklch(0.72 0.12 45);
  --accent-fg: oklch(0.18 0.02 50);
  --line: oklch(0.94 0.012 78 / 12%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 3px oklch(0.72 0.12 45 / 22%);
}
.theme-minimal-warm.alt-mode a { color: oklch(0.76 0.11 50); text-decoration-color: oklch(0.76 0.11 50 / 40%); }
.theme-minimal-warm.alt-mode ::selection { background: oklch(0.42 0.07 50); color: var(--fg); }
.theme-minimal-warm.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.4 0.03 60); border-color: var(--bg); }
.theme-minimal-warm.alt-mode .label-caps { color: oklch(0.72 0.09 50); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
